import {holes,forecast,clock} from './pace.js';
const names=['The Opening Drive','Pine Passage','Across the Water','The Gentle Bend','High Ground','The Short Game','Through the Pines','A Quiet Corner','The Turn','A Fresh Start','The Narrow Line','Lakeside','The Long View','Into the Wind','The Approach','Homeward Bound','One More Chance','The Home Green'];
const descriptions=['A fresh fairway and the whole round ahead.','Follow the fairway between the pines.','A little water. A little extra focus.','Let the course lead you around the bend.','Take in the view before your next shot.','A shorter hole, with plenty to think about.','Find your rhythm in the shade of the pines.','A calm stretch before the halfway point.','Nine holes in. A good moment to check your pace.','New fairways. The same good rhythm.','Pick your line and keep the round moving.','A quiet green beside the water.','Room to breathe, and a view to remember.','Stay with your group as the course opens up.','Keep the next group in sight, when it is safe.','The clubhouse is getting a little closer.','One more chance for a memorable shot.','One final putt. Then back to the clubhouse.'];
// Illustrative layout only; never used as geographic coordinates.
const centers=[[200,1220],[350,1080],[180,910],[330,750],[190,570],[340,410],[210,240],[410,150],[540,310],[580,490],[480,670],[620,830],[470,1000],[640,1160],[790,1010],[790,800],[800,570],[760,300]];
const safe=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
export function journeyRows(group,groups){
 const f=forecast(group,groups);
 return holes.map((target,i)=>{const h=i+1,a=f.arrivals.find(x=>x.hole===h);const passed=h<group.hole,current=h===group.hole;return {hole:h,target,passed,current,eta:passed?'Played':current?'Playing now':clock(a.at),etaLabel:passed?'ROUND PROGRESS':current?'ON THIS HOLE':'ESTIMATED ARRIVAL',exit:passed?null:clock(f.arrivals.find(x=>x.hole===h+1)?.at??f.finish),occupancy:groups.filter(g=>g.hole===h).length};});
}
function landscape(){const route=centers.map(([x,y])=>`${x},${y}`).join(' ');return `<svg class="journey-map" viewBox="-40 960 480 500" role="img" aria-label="Illustrated golf course. The map follows the hole in view; not a GPS map."><defs><pattern id="j-grass" width="28" height="28" patternUnits="userSpaceOnUse"><path d="M2 5l2 -3M17 21l2 -3" stroke="#294d3c" stroke-width=".8" opacity=".6"/></pattern><pattern id="j-mown" width="35" height="35" patternUnits="userSpaceOnUse" patternTransform="rotate(26)"><rect width="18" height="35" fill="#8fa766" opacity=".25"/></pattern><filter id="j-shadow" x="-50%" y="-50%" width="200%" height="200%"><feDropShadow dx="3" dy="5" stdDeviation="3" flood-opacity=".18"/></filter></defs><rect x="-1000" y="-1000" width="4000" height="4000" fill="#234837"/><rect width="1000" height="1400" fill="url(#j-grass)"/><path d="M-100 1090 Q190 1200 270 1020 T490 800 T600 510 T1000 350" fill="none" stroke="#63785a" stroke-width="7" opacity=".45"/><path d="M385 890 Q380 825 425 805 Q490 810 476 868 Q470 930 430 950 Q400 950 385 890ZM680 520 Q630 445 670 384 Q715 359 724 405 Q780 426 750 490 Q730 540 680 520Z" fill="#427c79" stroke="#7eae97" stroke-width="3"/><path d="M401 883Q400 845 429 834M695 480Q667 445 690 410" fill="none" stroke="#99b7a2" stroke-width="2" opacity=".5"/>
${Array.from({length:145},(_,i)=>{const x=(i*137+29)%980,y=(i*229+71)%1390;return `<g transform="translate(${x} ${y})" opacity=".8"><circle r="${10+i%6}" fill="#1d3e30"/><circle cx="-3" cy="-4" r="${8+i%5}" fill="#355940"/><circle cx="-5" cy="-6" r="${4+i%3}" fill="#416548"/></g>`;}).join('')}
<polyline points="${route}" fill="none" stroke="#d3dfae" stroke-width="2" stroke-dasharray="5 10" opacity=".3"/>
${centers.map(([x,y],i)=>`<g class="journey-map-hole" data-map-hole="${i+1}"><g transform="translate(${x} ${y}) rotate(${i%2?-25:24})"><path d="M-19 73 Q-44 34 -20 -12 Q-5 -33 -21 -63 Q-33 -94 -4 -108 Q29 -115 34 -86 Q48 -59 20 -28 Q9 -6 24 20 Q48 51 21 78 Z" fill="#718c53" stroke="#8ca568" stroke-width="3"/><path d="M-19 73 Q-44 34 -20 -12 Q-5 -33 -21 -63 Q-33 -94 -4 -108 Q29 -115 34 -86 Q48 -59 20 -28 Q9 -6 24 20 Q48 51 21 78 Z" fill="url(#j-mown)"/><ellipse cy="-82" rx="22" ry="26" fill="#abc57a"/><path d="M30 -63 Q52 -73 50 -44 Q39 -28 28 -44Z" fill="#e0d2a7"/><ellipse cx="-29" cy="29" rx="9" ry="15" fill="#dfd0a5"/><rect x="-12" y="65" width="24" height="11" rx="4" fill="#9eb276"/></g><circle class="hole-halo" cx="${x}" cy="${y-10}" r="40" fill="none" stroke="#d9efb6" stroke-width="2"/><g transform="translate(${x} ${y-10})"><circle class="hole-marker" r="17" fill="#18392c" stroke="#bbce99" stroke-width="1.5"/><text text-anchor="middle" dy="4" fill="#e5edcf" font-size="12" font-family="sans-serif">${i+1}</text></g><g transform="translate(${x+8} ${y-93})"><path d="M0 0v25" stroke="#f8f0d4" stroke-width="2"/><path d="M0 0l18 5 -18 6Z" fill="#f4e7ba"/></g></g>`).join('')}
<g transform="translate(75 1310)"><rect width="120" height="45" rx="5" fill="#b4ad91"/><path d="M-10 0L60 -32 130 0Z" fill="#7d8466"/><text x="60" y="65" text-anchor="middle" fill="#c6d0ad" font-size="9" letter-spacing="2">CLUBHOUSE</text></g></svg>`;}
export function journeyMarkup(group,groups){const rows=journeyRows(group,groups),f=forecast(group,groups);return `<section class="journey-intro"><div><span class="journey-kicker">THE COURSE JOURNEY</span><h2>Eighteen holes.<br>One beautiful flow.</h2><p>Scroll through the fairways. See what’s ahead,<br class="desktop-break"> and when your group will get there.</p><a class="journey-start" href="#journey-hole-1">Explore the course <span>↓</span></a></div><div class="journey-round"><label for="journey-group">FOLLOW A GROUP</label><select id="journey-group">${groups.map(g=>`<option value="${g.id}" ${g.id===group.id?'selected':''}>${safe(g.name)}</option>`).join('')}</select><div><span>TEE TIME<strong>${clock(group.tee)}</strong></span><span>EST. FINISH<strong>${clock(f.finish)}</strong></span></div><p>Simulated ETAs · illustrative course</p><button class="journey-current" data-jump-hole="${Math.min(18,group.hole)}">Jump to ${group.hole>18?'the final hole':`current hole ${group.hole}`} ↗</button></div></section><div class="journey-scroll"><div class="journey-visual"><div class="journey-scene">${landscape()}<div class="journey-map-heading"><span>PINE VALLEY</span><small>ILLUSTRATED COURSE · DEMO</small></div><div class="journey-compass">N<br>↑</div><div class="journey-map-caption"><span>FOLLOW THE FAIRWAY</span><strong id="journey-map-title">01 <small>/ 18</small></strong><div class="journey-progress"><div></div></div></div></div></div><div class="journey-story">${rows.map((r,i)=>`<article class="hole-chapter ${i===0?'is-active':''}" id="journey-hole-${r.hole}" data-chapter="${r.hole}" aria-labelledby="hole-title-${r.hole}"><div class="chapter-card"><div class="chapter-top"><span>${i<9?'THE FRONT NINE':'THE BACK NINE'}</span><span>${String(r.hole).padStart(2,'0')} / 18</span></div><span class="chapter-number">${String(r.hole).padStart(2,'0')}</span><h2 id="hole-title-${r.hole}">${names[i]}</h2><p>${descriptions[i]}</p><div class="chapter-eta"><div><span>${r.etaLabel}</span><strong>${r.eta}</strong></div><span class="chapter-state ${r.passed?'passed':r.current?'current':''}">${r.passed?'✓ Completed':r.current?'● Your group is here':'↗ Coming up'}</span></div><div class="chapter-stats"><span>HOLE TARGET<strong>${r.target} <small>min</small></strong></span><span>${r.passed?'COURSE TRAFFIC':'EST. CLEAR HOLE'}<strong>${r.passed?`${r.occupancy} groups`:r.exit}</strong></span></div><div class="chapter-bottom"><span>${r.occupancy===0?'Clear in the simulation':`${r.occupancy} group${r.occupancy===1?'':'s'} on this hole`}</span><button data-hole="${r.hole}" aria-label="View hole ${r.hole} traffic">View traffic ↗</button></div>${r.passed?'<small class="chapter-note">Past arrival times were not recorded in this demo.</small>':''}${i<17?`<a class="chapter-next" href="#journey-hole-${r.hole+1}">Next fairway <span>↓</span></a>`:'<div class="journey-finish">⚑ &nbsp; A good walk, all the way home.</div>'}</div></article>`).join('')}</div></div><div class="journey-end"><span class="journey-kicker">BACK AT THE CLUBHOUSE</span><h2>Every good round has a rhythm.</h2><p>ETAs update when you advance the simulation or select another group.</p><a href="#journey-hole-1" class="journey-start">Back to the first tee ↑</a></div>`;}
export function mountJourney(root){
 const chapters=[...root.querySelectorAll('[data-chapter]')],svg=root.querySelector('.journey-map');
 if(!svg||!chapters.length)return ()=>{};
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 let frame=0,active=-1,disposed=false;
 function update(){frame=0;if(disposed)return;const mobile=matchMedia('(max-width: 760px)').matches;const focus=innerHeight*(mobile?.66:.53);let index=0;
 for(let i=0;i<chapters.length;i++){if(chapters[i].getBoundingClientRect().top<=focus)index=i;}
 const rect=chapters[index].getBoundingClientRect();
 const progress=Math.max(0,Math.min(1,(focus-rect.top)/Math.max(1,rect.height)));
 const t=reduced.matches?0:progress*progress*(3-2*progress),next=Math.min(17,index+1);
 const x=centers[index][0]+(centers[next][0]-centers[index][0])*t;
 const y=centers[index][1]+(centers[next][1]-centers[index][1])*t;
 svg.setAttribute('viewBox',`${x-240} ${y-260} 480 500`);
 root.querySelector('.journey-progress div').style.width=`${(index+progress)/18*100}%`;
 if(index!==active){active=index;chapters.forEach((c,i)=>c.classList.toggle('is-active',i===index));root.querySelectorAll('[data-map-hole]').forEach((c,i)=>c.classList.toggle('map-active',i===index));root.querySelector('#journey-map-title').innerHTML=`${String(index+1).padStart(2,'0')} <small>/ 18</small>`;}
 }
 function schedule(){if(!frame)frame=requestAnimationFrame(update);}
 function jump(e){const anchor=e.target.closest('a[href^="#journey-hole-"]'),button=e.target.closest('[data-jump-hole]');if(!anchor&&!button)return;const target=root.querySelector(anchor?.getAttribute('href')||`#journey-hole-${button.dataset.jumpHole}`);if(target){e.preventDefault();target.scrollIntoView({behavior:reduced.matches?'instant':'smooth',block:'start'});target.focus({preventScroll:true});}}
 chapters.forEach(c=>c.tabIndex=-1);
 root.addEventListener('click',jump);window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule);reduced.addEventListener('change',schedule);update();
 return ()=>{disposed=true;cancelAnimationFrame(frame);root.removeEventListener('click',jump);window.removeEventListener('scroll',schedule);window.removeEventListener('resize',schedule);reduced.removeEventListener('change',schedule);};
}
